exec(open("batches/hiv_common.py").read())
# HIV 2022 part 3, pp.176-183 (Chapter 8: PMTCT prongs, prevention, family planning, conception, ANC services). Cell text from the PDF
# ruled grid; layout checked on the page images.
C8 = "Chapter 8: Prevention of Mother to Child Transmission of HIV"
ITEMS = [
 B("box-8-dbs-hotline", 176, C8, "Important contact (PMTCT)", [], "DBS Hotline: 7687-9925"),
 T("tbl-8.1-pmtct-prongs", 177, C8 + " > PMTCT Strategy > Table 8.1 PMTCT Prongs", "Table 8.1 PMTCT Prongs", ["0477"],
   [r("Prong", "Description", "Target Population", "Section")],
   [r(*x) for x in [["Prong 1", "Primary prevention of HIV infection among women of childbearing age", "Non-pregnant HIV-negative women of childbearing age including adolescents and their partners", "Section 8.1"], ["Prong 2", "Prevention of unintended pregnancies among HIV-positive women and access to other Sexual and Reproductive Health (SRH) services", "Non-pregnant HIV-positive women of childbearing age including adolescents and their partners", "Section 0"], ["Prong 3", "PMTCT among HIV-positive pregnant and lactating women", "Pregnant and lactating women", "Section 8.3"], ["Prong 4", "Care, support and treatment for HIV-positive women and their families", "HIV-infected women, their children, partners and families", "Section 8.4, Section 8.7"]]],
   source_flags=["Prong 2 cross-reference reads 'Section 0' (broken; the section is 8.2)."]),
 T("tbl-8.2-prevention-non-pregnant", 177, C8 + " > 8.1 Primary Prevention of HIV Infection among Women of Childbearing Age > Table 8.2", "Table 8.2 HIV Prevention Services for Non-Pregnant Women", ["0479", "0480", "0481", "0482"],
   [r("Service", "Description")], [r(a, b) for a, b in [["HIV testing services (HTS)", "• Provide routine HTS services for all women of childbearing age visiting the health facility and their male partners, and referral for prevention, care and treatment services.<br/>• Women currently in an active sexual relationship should ideally be tested as a couple where feasible.<br/>• Distribute HIVST kits for partners of women of childbearing age (15-49 years)<br/>• See Chapter 3 on HTS for more details"], ["Provide sexually transmitted infection (STI) screening and management", "• Provide STI screening for women and their partners and ensure all STIs detected are managed appropriately.<br/>• See National STI guidelines for more details."], ["HIV prevention counselling and safer sex", "• Provide information and counselling on HIV prevention and how to reduce the risk of sexual HIV transmission.<br/>• All clients should be offered PrEP at each visit. Inform clients of the safety and efficacy of PrEP<br/>• Promote correct and consistent use of female and male condoms for the woman and her partner, emphasizing the benefits of dual protection:<br/>o Give reasons and benefits for using condoms.<br/>o Dispel myths and misconceptions about condoms.<br/>o Demonstrate condom use and teach condom negotiation skills.<br/>o Promote/teach mutual assistance in using condoms and ensure both partners’ involvement.<br/>o Encourage joint decision-making with both partners on visits to the health facility for care, condom usage, etc. See Chapter 2 on Prevention for more details."], ["Provide gender-based violence (GBV) prevention and impact mitigation services", "• Provide information to empower women on gender equality and equity—sexual and reproductive health rights.<br/>• Provide counselling, HTS, emergency contraception, HIV/STI post-exposure prophylaxis and psychosocial support, and screen for and manage Hepatitis B from survivors of gender-based violence.<br/>• Provide information on services and organizations specialising in gender-based violence.<br/>• Refer people who have experienced or are experiencing gender-based violence to appropriate services, including legal and psychological support services (e.g., Eswatini Action Group Against Abuse (SWAGAA) centres or One-Stop-Centres)."], ["Provide men’s minimum health care package to partners of the women visiting the health facility", "• Emphasize the partner’s role in HIV prevention (for himself, partner and child); including discussing gender-based violence, cultural norms and practices; and the importance of partner support.<br/>• Educate and counsel the client on men’s health issues or refer the male client for sexual and reproductive health services<br/>• Advise on a healthy lifestyle—diet and exercise, alcohol, and substance use.<br/>• Provide prevention measures:<br/>• Offer HTS – couple testing and appropriate linkage to prevention or care and treatment services.<br/>o Screen and treat STIs, TB, NCDs, and other conditions as needed.<br/>o Demonstrate correct use of male and female condoms. Promote voluntary medical male circumcision (VMMC) for HIV-negative men and refer and link men to VMMC services. Emphasize dual protection: VMMC and correct and consistent condom use<br/>o Advise on available services for early infant medical circumcision (EIMC) for male new-borns and male siblings."]]], pages=[177, 178]),
 T("tbl-8.3-unintended-pregnancy", 179, C8 + " > 8.2 Prevention of Unintended Pregnancies in Women Living with HIV > Table 8.3", "Table 8.3 Services to Prevent Unintended Pregnancies", ["0484"],
   [r("Service", "Description")], [r(a, b) for a, b in [["Provide information and services to support family planning and reproductive rights", "• All PLHIV should be offered family planning services according to the National Guidelines on Integration of Family Planning in HIV Services.<br/>• Support women and couples to identify reproductive goals.<br/>• Counsel on the safety of and eligibility of the full range of contraceptives and family planning methods, including emergency contraception and permanent methods, in the context of HIV. s • Provide adolescent-friendly family planning counselling. Adhere to confidentiality and encourage t independent decision-making of adolescents.<br/>• Family Planning (FP) services should be integrated with all other HIV services (e.g., ART initiation and refill) d<br/>• Encourage the use of long-term reversible contraceptive methods and dispel myths about side effects and return to fertility<br/>• All forms of family planning are appropriate for use with DTG in women and adolescents<br/>• Diagnose pregnancy early and inquire/document the last menstrual period in all women of childbearing age.<br/>• All HIV positive women should be on ART"]]]),
 T("tbl-8.4-conception-advice", 179, C8 + " > 8.2.1 Advice for Couples Considering Having a Child > Table 8.4", "Table 8.4 Advice for Couples Who are Considering Having a Child", ["0486", "0487"],
   [r("Couple", "Advice")], [r("Both are positive", "• Provide adequate counselling around risks reduction, reinfection and risks of mother-to-child transmission of HIV<br/>• Before making recommendations, assess the couple clinically, immunologically and virologically.<br/>• If a woman is not on ART, she should be initiated on ART as soon as possible.<br/>• If a man is not on ART, he should be initiated on ART as soon as possible.<br/>• If the couple is already on ART, ensure undetectable viral load.<br/>• If the viral load is undetectable, advise on fertility days and timed ovulatory intercourse (condom use at all other times).<br/>• Prevent/treat STIs."), r("Serodifferent couples", "• Provide adequate counselling around risks of infection of the negative partner and risks of mother-to-child transmission.<br/>• Provide ART to the HIV-positive partner as soon as possible, if not already on ART.<br/>• If the positive partner is already on ART, ensure they have an undetectable viral load.<br/>• If the viral load is undetectable, advise on fertility days and timed ovulatory intercourse (use of condoms at all other times).<br/>• Advise the couple to wait until viral load is undetectable before trying to conceive on fertility days<br/>• Consider pre-exposure prophylaxis (PrEP) for the HIV-negative partner.")], pages=[179, 180],
   context_before="The final decision to conceive depends on the couple. HCWs should provide accurate and unbiased information necessary to support their decision-making.", source_flags=["Column headings added (none in the PDF)."]),
 T("tbl-8.5-retesting-pregnant", 180, C8 + " > 8.3 Antenatal Care for Pregnant Women to Prevent Mother to Child Transmission > Table 8.5", "Table 8.5 Retesting schedule for Pregnant Women in Antenatal Care", ["0489"],
   [r("Population", "Retesting and prevention")], [r("HIV-negative Women", "• As part of efforts to achieve the elimination of MTCT, all HIV-negative pregnant and lactating women should be offered PrEP using the OPT OUT approach. If a woman deems herself low risk after complete discussion regarding PrEP benefits, clearly document refusal and offer PrEP again at the next visit.<br/>• Pregnant and lactating women on PrEP should be retested one month after initiation. PrEP refills and testing will align with the ANC or CWF/ MBP visits.<br/>• All HIV-negative pregnant women not on PrEP should be re-tested every 2 months (aligned with the ANC scheduled visits) with the most optimal time for retesting being during the third trimester visit (34 weeks gestation).<br/>• All HIV-negative lactating women should be re-tested at 6 weeks, 14 weeks, 6 months, 9 months, 12 months, 15 months and 18 months aligned with the MBP follow-up schedule.<br/>• For pregnant and lactating women with inconclusive results after HTS; conduct Nucleic Acid Amplification Tests (NAAT) – DNA PCR, and initiate ART immediately while waiting for NAAT results")],
   context_before="The first antenatal care (ANC) visit should occur as soon as the woman realizes she is pregnant, preferably within the first trimester (0-12 weeks of gestation).", source_flags=["Column headings added (none in the PDF)."]),
 T("tbl-8.6-anc-key-services", 181, C8 + " > 8.3 > Summary of Key Services for Pregnant Women in Antenatal Care > Table 8.6", "Table 8.6 Key Services for Pregnant Women in Antenatal Care", ["0490", "0491", "0492"],
   [r("Service", "Description")], [r(a, b) for a, b in [["Comprehensive history-taking and examination", "• Take medical history including obstetric, family and psychosocial history.<br/>• IPV increases during pregnancy, in the event of reported or suspected cases of IPV, refer to the National GBV Guidelines for management.<br/>• Mental health screening"], ["Tuberculosis screening", "• Screen all women regardless of HIV status for TB using the National TB/Covid-19 Screening Tool.<br/>• Refer or provide diagnostic and follow-up services according to National TB Management Guidelines.<br/>• All pregnant and lactating women are at high risk for TB and are eligible for TPT."], ["Nutritional assessment, counselling, and support", "• Assessment: Assess nutritional status using mid-upper arm circumference.<br/>• Counselling: Counsel on a proper diet based on locally available foods.<br/>• Nutritional support and supplements: Provide ferrous sulphate, folic acid and multivitamins. For women with a mid-upper arm circumference of less than 23cm, enrol on or refer to food by prescription support."], ["HTS pregnant woman and her partner", "See Chapter 3 for HTS Guidance including index testing and partner notification guidance.<br/>• Re-test all HIV-negative pregnant women every 2 months. The re-testing dates should be aligned to the woman’s scheduled contact visits. Offer PrEP each visit.<br/>• Pregnant women declining HTS should continue receiving ongoing counselling at every subsequent ANC visit on the importance of knowing their status."], ["Laboratory investigations and treatment of identified conditions", "• See Chapter 5, Section 5.2 for routine tests.<br/>• Routine laboratory tests: Haemoglobin, blood group and Rh factor, urinalysis, HBsAg, malaria RDT and syphilis, and provide treatment for any anomaly according to national guidelines<br/>• Additional tests for HIV-infected pregnant women: CD4 cell count, liver function tests, and renal function tests (and calculate creatinine clearance); viral load for women on ART according to Figure 8.1 ART initiation should not be delayed while awaiting results for these tests.<br/>• Any detectable viral load in pregnant women should be treated with urgency"], ["Immunization", "• Give tetanus toxoid and other immunizations according to National EPI Guidelines.<br/>• COVID-19 vaccination is of particular importance given the increased morbidity/mortality from SARS-Cov2 infection during pregnancy."], ["Counselling and education", "• Provide HTS for HIV-negative women as outlined in Section 8.1<br/>• Educate appropriately on:<br/>o Family Planning- emphasise dual protection<br/>o Pregnancy and Delivery (including danger signs)<br/>o Birth preparedness planning<br/>o Infant and young child feeding, see sub-section 8.12<br/>o Early Infant Male Circumcision, see Chapter 2, section 2.4.<br/>o Harmful habits *<br/>• Emphasize adherence to PrEP for the HIV-negative and ART for the HIV-positive. Emphasize that PrEP is safe for the baby throughout pregnancy and breastfeeding.<br/>• Provide psychosocial support, including partner and family support."], ["Refer high-risk pregnancies", "Refer women with high-risk pregnancies to higher-level institutions. These include pregnancy-induced hypertension, diabetes, previous caesarean sections or pregnancy complications, multiple pregnancies, multiple miscarriages, heart disease, or any other pre-existing medical condition that should be referred. Women with viremia on 2nd or 3rd line ART are considered high risk"]]], pages=[181, 182],
   source_flags=["Harmful habits is marked * but the asterisk is not explained."]),
 T("tbl-8.7-hiv-positive-anc", 182, C8 + " > 8.3.1 PMTCT Package for HIV-Positive Women in Antenatal Care > Table 8.7", "Table 8.7 Key Considerations for HIV-positive Women in Antenatal Care", ["0493", "0494", "0495", "0496", "0497"],
   [r("Service", "Description")], [r(a, b) for a, b in [["ALL HIV-Positive Women", "• All pregnant women testing HIV-positive should be re-tested for verification before initiation of ART.<br/>• All newly diagnosed HIV-positive pregnant women not yet on ART, regardless of gestational age, should be initiated on ART at the first ANC visit while maintaining ongoing counselling.<br/>• ART services for pregnant women should be provided within ANC settings. Virally suppressed mothers enrolled in a DSD model may continue to do so provided that all VLs are done on time (First ANC, 2nd trimester and 32-36 weeks).<br/>• Viral load testing should be done for all HIV-positive pregnant women already on ART at the first ANC visit, then follow the viral load schedule for subsequent tests<br/>• All HIV-positive pregnant and lactating women should be on ART with an undetectable viral load. A detectable viral load should be treated with urgency See Table 8.9<br/>• Initiate Co-trimoxazole 960 mg as outlined in section (Chapter 5, Section 5.4), TPT, and Vitamin B6 25mg PO daily for women who are eligible and not already taking it. See Chapter 6, Section 6.1.5.<br/>• Give enhanced infant prophylaxis (eIP): NVP (25ml bottle) and AZT(100ml bottle) with a syringe and provide instructions for the mother to give the baby 1.5 mL of NVP daily and 1.5 mL of AZT twice a day. Label bottles clearly to avoid confusion. AZT is given for 6 weeks post-partum. NVP is given a minimum of 14 weeks and/or until the mother is undetectable. Refer to Table 8.10 for dosing"], ["Newly positive OR known positive not on ART", "• First-line ART regimen for pregnant women is TDF + 3TC + DTG.<br/>• Initiate ART as soon as possible at any gestational age, preferably on the same day and in the ANC clinic. CD4 Count should be done at initiation to identify AHD, however ART initiation should not be postponed in the absence of a CD4 count result<br/>• Ensure the mother understands the significance of ART adherence once initiated. If she adheres well to ART, reassure her that her baby will be HIV-free.<br/>• Schedule a follow-up visit for the woman in two weeks to review baseline tests and make any necessary ART changes if needed Monitor Viral load 3 months after initiation as per the VL schedule. See Figure 8.1"], ["Already on ART", "• Conduct viral load (VL) testing on the first ANC contact, regardless of prior VL testing dates and the subsequent VL test must be done at 34 weeks gestation. See Figure 8.1 below<br/>• If there is no evidence of treatment failure (VL <50copies/ml) continue the current ART regimen.<br/>• If VL is detectable (>50 copies/ml), initiate SUAC and refer to doctor, mother facility and/or Baylor<br/>• Any HIV positive pregnant woman with a detectable viral load at contact requires URGENT intervention:<br/>o If VL is detectable (>50copies/ml) and on a DTG-based 1st line regimen, ART should be switched to a DTG-based 2nd line regimen with concurrent SUAC started on the same day. See Table 7.11<br/>o If VL is detectable on a DTG-based first line should have expedited SUAC and follow-up VL in 6-8 weeks. Do not wait 3 months.<br/>o Suspected 2nd line failures (DTG or PI-based) should have a genotype sent the same day and then be placed on a 3rd line holding regimen while awaiting further guidance from the HIVDR committee: Consult snapthirdline@mohcoag.org or Baylor for regimen selection and dosing"], ["Not ready for ART", "• Enrol into eLCM<br/>• Assure the patient’s understanding and willingness to provide eIP.<br/>• Counsel women on the benefits of early initiation on ART for their health, for the child and partner(s).<br/>• Address any fears and/or barriers for the woman not ready to initiate ART, including partner support.<br/>• Follow-up in 2 weeks and initiate ART if she is ready.<br/>• If she is still not ready for ART, continue counselling at every visit. Discuss options for supplementary feeding of the infant.<br/>• Link client with Community Mentor Mother adolescent supporters and all local resources for additional counselling and support<br/>• Follow up with the woman in 2 weeks and initiate ART if she is ready.<br/>• If the woman is still not ready for ART, continue counselling at every visit. Assure her understanding and willingness to provide eIP."]]], pages=[182, 183],
   source_flags=["Already on ART: the first sub-bullet says to switch to a DTG-based 2nd line at once if VL >50 on DTG first line, the next says to do expedited SUAC and repeat VL in 6-8 weeks ('Do not wait 3 months'); Table 7.11 requires resistance testing before leaving DTG and switching only to a boosted PI.",
                 "Enhanced infant prophylaxis here: AZT for 6 weeks and NVP for a minimum of 14 weeks; check against Table 8.10 and the 2024 Amendment (Chapter 8)."]),
]
